import { test, expect } from '@playwright/test';

test.describe('Export Personal Data as JSON', () => {
  const baseURL = process.env.BASE_URL || 'http://localhost:3000';

  test.beforeEach(async ({ page }) => {
    await page.goto(`${baseURL}/login`);
    await page.getByLabel('Email').fill('testuser@example.com');
    await page.getByLabel('Password').fill('TestPassword123!');
    await page.getByRole('button', { name: /sign in/i }).click();
    await page.waitForURL(`${baseURL}/dashboard`);
  });

  test('should successfully export personal data as JSON file', async ({ page, context }) => {
    // Navigate to profile settings
    await page.goto(`${baseURL}/profile/settings`);

    // Verify we're on the correct page
    await expect(page.getByRole('heading', { name: /profile settings/i })).toBeVisible();

    // Click on the export data section
    await page.getByRole('button', { name: /export my data/i }).click();

    // Verify export dialog appears
    await expect(page.getByRole('dialog')).toBeVisible();
    await expect(page.getByText(/export your personal data/i)).toBeVisible();

    // Start listening for download
    const downloadPromise = context.waitForEvent('download');

    // Click the export button
    await page.getByRole('button', { name: /export as json/i }).click();

    // Wait for download to complete
    const download = await downloadPromise;

    // Verify download filename
    expect(download.suggestedFilename()).toMatch(/personal-data.*\.json$/);

    // Verify file path exists
    const path = await download.path();
    expect(path).toBeTruthy();
  });

  test('should display confirmation message after successful export', async ({ page, context }) => {
    // Navigate to profile settings
    await page.goto(`${baseURL}/profile/settings`);

    // Click on the export data section
    await page.getByRole('button', { name: /export my data/i }).click();

    // Wait for dialog to be visible
    await expect(page.getByRole('dialog')).toBeVisible();

    // Start listening for download
    const downloadPromise = context.waitForEvent('download');

    // Click the export button
    await page.getByRole('button', { name: /export as json/i }).click();

    // Wait for download
    await downloadPromise;

    // Verify success message appears
    await expect(page.getByText(/your data has been exported successfully/i)).toBeVisible();

    // Verify dialog closes after export
    await expect(page.getByRole('dialog')).not.toBeVisible({ timeout: 5000 });
  });

  test('should allow user to cancel export operation', async ({ page }) => {
    // Navigate to profile settings
    await page.goto(`${baseURL}/profile/settings`);

    // Click on the export data section
    await page.getByRole('button', { name: /export my data/i }).click();

    // Verify export dialog appears
    await expect(page.getByRole('dialog')).toBeVisible();

    // Click cancel button
    await page.getByRole('button', { name: /cancel/i }).click();

    // Verify dialog is closed
    await expect(page.getByRole('dialog')).not.toBeVisible();

    // Verify we're still on the profile settings page
    await expect(page.getByRole('heading', { name: /profile settings/i })).toBeVisible();
  });

  test('should include all required data fields in exported JSON', async ({ page, context }) => {
    // Navigate to profile settings
    await page.goto(`${baseURL}/profile/settings`);

    // Click on the export data section
    await page.getByRole('button', { name: /export my data/i }).click();

    // Wait for dialog
    await expect(page.getByRole('dialog')).toBeVisible();

    // Start listening for download
    const downloadPromise = context.waitForEvent('download');

    // Click the export button
    await page.getByRole('button', { name: /export as json/i }).click();

    // Wait for download to complete
    const download = await downloadPromise;

    // Read the downloaded file
    const path = await download.path();
    const fs = require('fs');
    const fileContent = fs.readFileSync(path, 'utf-8');
    const jsonData = JSON.parse(fileContent);

    // Verify required fields exist in the exported data
    expect(jsonData).toHaveProperty('personalInfo');
    expect(jsonData).toHaveProperty('email');
    expect(jsonData).toHaveProperty('accountCreatedDate');
    expect(jsonData.personalInfo).toHaveProperty('firstName');
    expect(jsonData.personalInfo).toHaveProperty('lastName');
  });

  test('should show loading state during export process', async ({ page }) => {
    // Navigate to profile settings
    await page.goto(`${baseURL}/profile/settings`);

    // Click on the export data section
    await page.getByRole('button', { name: /export my data/i }).click();

    // Wait for dialog
    await expect(page.getByRole('dialog')).toBeVisible();

    // Click the export button
    const exportButton = page.getByRole('button', { name: /export as json/i });
    await exportButton.click();

    // Verify loading indicator appears
    await expect(page.getByRole('status')).toContainText(/exporting/i);

    // Wait for loading to complete
    await expect(page.getByText(/your data has been exported successfully/i)).toBeVisible({ timeout: 10000 });
  });
});
